import * as React from 'react'
import { Button, type ButtonProps } from '@/components/ui/button'
import { useInputType } from '@/hooks/use-input-type'
import { announce } from '@/lib/announce'

export interface ConfirmButtonProps
  extends Omit<ButtonProps, 'variant' | 'onClick' | 'children'> {
  /** Label shown in the default (un-armed) state. */
  label: string
  /**
   * Label shown after the first tap/click arms the button (touch input).
   * Typically the translated form of "Tap again to confirm".
   */
  touchConfirmLabel: string
  /**
   * Label shown after the first click arms the button (mouse/keyboard input).
   * Typically the translated form of "Click again to confirm".
   */
  mouseConfirmLabel: string
  /** Called only when the button is tapped/clicked a second time while armed. */
  onConfirm: () => void
  /**
   * Controls the armed state from outside, e.g. to reset it when a drawer
   * closes. When provided the component is controlled; when omitted it manages
   * its own state.
   */
  armed?: boolean
  /** Called when the internal armed state changes (controlled usage). */
  onArmedChange?: (armed: boolean) => void
}

/**
 * Destructive action button with a tap-again-to-confirm pattern.
 *
 * Tap/click once to arm it (label switches to confirm prompt). Tap/click again
 * to execute `onConfirm`. The armed state is managed internally unless you pass
 * `armed` + `onArmedChange` for controlled usage (e.g., to reset it when the
 * enclosing drawer closes).
 *
 * Input type detection via `useInputType` automatically picks between
 * `touchConfirmLabel` and `mouseConfirmLabel`.
 *
 * Built on the DS `Button` with `variant="destructive"`.
 */
export const ConfirmButton = React.forwardRef<HTMLButtonElement, ConfirmButtonProps>(function ConfirmButton({
  label,
  touchConfirmLabel,
  mouseConfirmLabel,
  onConfirm,
  armed: controlledArmed,
  onArmedChange,
  ...rest
}, ref) {
  const inputType = useInputType()
  const [internalArmed, setInternalArmed] = React.useState(false)

  const isControlled = controlledArmed !== undefined
  const armed = isControlled ? controlledArmed : internalArmed

  const setArmed = React.useCallback(
    (next: boolean) => {
      if (!isControlled) setInternalArmed(next)
      onArmedChange?.(next)
    },
    [isControlled, onArmedChange]
  )

  const confirmLabel =
    inputType === 'touch' ? touchConfirmLabel : mouseConfirmLabel

  const handleClick = () => {
    if (armed) {
      onConfirm()
      setArmed(false)
    } else {
      setArmed(true)
      // Announce the confirm prompt assertively so screen-reader users know
      // the next activation will execute the destructive action.
      announce(confirmLabel, 'assertive')
    }
  }

  return (
    <Button ref={ref} variant="destructive" onClick={handleClick} {...rest}>
      {armed ? confirmLabel : label}
    </Button>
  )
})

ConfirmButton.displayName = "ConfirmButton"
